WITH norm AS (SELECT id, created_at, LOWER(REGEXP_REPLACE(COALESCE(question_data->>'instruction','')||'|'||COALESCE(question_data->>'column_a','')||'|'||COALESCE(question_data->>'column_b','')||'|'||COALESCE((question_data->'options')::text,'{}'),'\s+','','g')) AS fp FROM public.practice_questions), dups AS (SELECT id FROM (SELECT id, ROW_NUMBER() OVER (PARTITION BY fp ORDER BY created_at ASC, id ASC) rn FROM norm WHERE fp <> '|||{}') t WHERE rn > 1) UPDATE public.practice_questions p SET quality_status='remove', quality_reason='duplicate_internal' FROM dups WHERE p.id = dups.id;